"""Always-visible payment summaries matching the approved mockup."""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
SUMMARY='''<section id="payment-options" class="drug-section drug-payment-summary" aria-labelledby="payment-summary-title">
<h2 id="payment-summary-title">What will I pay?</h2><p class="drug-summary-intro">Your starting point, at a glance. Open a row for eligibility and next steps.</p>
<div class="drug-summary-rows">
<details class="drug-summary-row" data-payment-row="private"><summary><span class="drug-summary-left"><strong>Private insurance</strong><span>Employer or marketplace plan</span><small>Manufacturer co-pay card · eligibility and limits apply</small></span><span class="drug-summary-right"><span class="drug-row-price"><span data-drug-price-prefix hidden>As little as </span><span data-drug-copay>Check current offer</span></span><small data-drug-supply>Confirm the eligible supply</small></span><span class="drug-summary-chevron" aria-hidden="true">⌄</span></summary><div class="drug-summary-body"><p data-drug-eligibility>A manufacturer card may reduce your share of an insured prescription. Check the program’s coverage requirements, eligibility, benefit limits, and expiration.</p><a class="drug-button" data-program-link="copay" href="#program-sources" aria-disabled="true">Review official program ↗</a><p class="drug-small" data-drug-price-source>Confirm current price and terms on the official program website.</p></div></details>
<details class="drug-summary-row" data-payment-row="government"><summary><span class="drug-summary-left"><strong>Government insurance</strong><span>Medicare, Medicaid, CHIP, TRICARE</span><small>Commercial co-pay card excluded; other support may apply</small></span><span class="drug-summary-right"><span class="drug-row-status">Plan-dependent</span></span><span class="drug-summary-chevron" aria-hidden="true">⌄</span></summary><div class="drug-summary-body"><p>Your plan determines your covered price. Commercial manufacturer co-pay cards generally exclude government coverage. Separate assistance and cash-pay routes have their own criteria.</p><div class="drug-summary-links"><a class="drug-text-link" href="https://www.ssa.gov/medicare/part-d-extra-help" target="_blank" rel="noopener">Check Medicare Extra Help ↗</a><a class="drug-text-link" data-government-assistance-link href="https://www.needymeds.org/" target="_blank" rel="noopener">Explore assistance resources ↗</a><a class="drug-text-link" href="#pharmacy-prices">Compare cash-pay alternatives ↓</a></div><p class="drug-small">For Medicaid or other government plans, ask your plan about your prescription benefits and support options.</p></div></details>
<details class="drug-summary-row" data-payment-row="cash"><summary><span class="drug-summary-left"><strong>No insurance / cash pay</strong><span>Self-pay patients</span><small>Compare pharmacy prices and assistance eligibility</small></span><span class="drug-summary-right"><span class="drug-row-price">Prices vary</span></span><span class="drug-summary-chevron" aria-hidden="true">⌄</span></summary><div class="drug-summary-body"><p data-drug-assistance>Some manufacturers or independent foundations offer assistance. Income, insurance, medication, and funding requirements vary. Assistance is not guaranteed.</p><div class="drug-summary-links"><a class="drug-button drug-button-light" href="#pharmacy-prices">Compare pharmacy prices ↓</a><a class="drug-text-link" data-program-link="assistance" href="https://www.needymeds.org/" target="_blank" rel="noopener">Look up assistance resources ↗</a></div><p class="drug-small">Compare the same dose, quantity, and supply. Discounts may not combine with insurance or count toward your deductible.</p></div></details>
</div><p class="drug-summary-note" data-summary-source>Program minimums are not your confirmed price. Check current terms; your actual cost depends on eligibility, coverage, and the prescribed supply.</p><div class="relief-source-status drug-source-status" role="status" aria-live="polite">Loading program details. No personal price is confirmed.</div>
</section>'''
ART='''<svg class="drug-pharmacy-drawing" viewBox="0 0 260 170" aria-hidden="true" focusable="false"><ellipse cx="140" cy="146" rx="109" ry="13" fill="#c9e8dd"/><path d="M66 66L164 55L216 78V146H66Z" fill="#fffefa" stroke="#26362f" stroke-width="2"/><path d="M164 55V146M66 66L48 52L154 34L216 57V78" fill="#eae8f7" stroke="#26362f" stroke-width="2" stroke-linejoin="round"/><path d="M48 52V78L164 69L216 78V57" fill="#fffefa" stroke="#26362f" stroke-width="2"/><path d="M105 46V62M97 54H113" stroke="#597a77" stroke-width="5"/><path d="M105 145V100H136V145M75 102H94V126H75ZM145 101H158V124H145ZM181 103H200V126H181Z" fill="#eae8f7" stroke="#26362f" stroke-width="2"/><path d="M28 145V98M235 145V103" stroke="#26362f" stroke-width="2"/><ellipse cx="28" cy="107" rx="10" ry="25" fill="#bce1cd" stroke="#26362f" stroke-width="2"/><ellipse cx="235" cy="112" rx="9" ry="23" fill="#bce1cd" stroke="#26362f" stroke-width="2"/></svg>'''
for p in list((ROOT/'drugs').glob('*/index.html'))+[ROOT/'templates/index.html']:
 s=p.read_text()
 if 'drug-conversion-v2' not in s or 'drug-summary-v3' in s:continue
 s=s.replace(' drug-conversion-v2',' drug-conversion-v2 drug-summary-v3',1)
 s=re.sub(r'<section id="payment-options".*?</section>',SUMMARY,s,count=1,flags=re.S)
 s=s.replace('<span class="drug-pharmacy-icon" aria-hidden="true">↔</span>',ART,1)
 s=s.replace('</head>','<link rel="stylesheet" href="/assets/css/drug-summary.css"></head>',1)
 p.write_text(s)
print('Applied always-visible summary rows to standard drug pages and template.')
